#include "TUIAsrInputProcessor.h"
#import "UIElementController.h"
@implementation TUIAsrInputProcessor
- (void) buttonTapped:(id)sender {
    UIElementController *controller = [self valueForKey:@"myBox"];
	UIElement *listener = [[UIElement]listener];

	[listener sendCommand:@"TUIAsrInputProcessorDelegate: button tapped" parameter: [[self view]valueForTextFieldAsr]];

    if ([controller receiverReply]!=nil) {
        [controller clearLogUIElement];
		[controller pauseChat];
        [controller cleanupDialog];
        [controller unload;
    } else {
        [controller clearLogUIElement];
        [controller blockAsrDialogWithReply:@"Done."];
		[controller publishMessageAsync:@"Done" replyingTo: [[controller receiverReply]from]];
		[controller beginChat];
		[controller resumeChat];
    }
}
@end

